-- Mod-authored natural wonder portrait descriptions, ko_KR overlay.
-- Baseline in CivVAccess_NaturalWonderDescStrings_en_US.lua.
CivVAccess_Strings = CivVAccess_Strings or {}

CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_MISSING"] = "이 자연 경관에 대한 설명이 없습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_CRATER"] =
    "거대한 운석 충돌 분화구를 그 가장자리에서 내려다본 모습으로, 창백한 사막 지면에 찍힌 울퉁불퉁한 사발 형태입니다. 가까운 비탈은 초록 관목으로 덮여 있다가 그림자에 잠긴 구덩이 속으로 떨어지며, 구덩이 바닥은 짙은 갈색 어둠 속에 잠겨 있고, 먼 가장자리는 자욱한 하늘 아래 황갈색과 금빛 띠를 이루며 솟아 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_EL_DORADO"] =
    "순금으로 이루어진 계단식 피라미드로, 그 정면을 따라 가파른 계단이 꼭대기의 작은 신전까지 이어집니다. 그 기단에는 거대한 금괴들이 가느다란 짙은 색 나무들 사이에 쌓여 있으며, 장면 전체가 노랗게 빛나 엘도라도라는 전설 속 도시의 보물이 그대로 구현되어 있습니다. 그 뒤로 비치는 빛줄기는 잃어버린 도시 위로 동이 트는 일출처럼 보입니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_FOUNTAIN_YOUTH"] =
    "비현실적일 만큼 밝은 청록색 물의 샘이 짙은 색 바위 절벽 위의 수반에서 솟아올라 아래 웅덩이로 빛나는 폭포가 되어 쏟아집니다. 검은 바위에는 초록 풀숲이 매달려 있고, 야자수 잎이 따뜻한 황금빛 하늘을 틀로 감싸며, 물 위에서 반짝이는 작은 빛들이 이 물이 자연의 것이 아니라 신비로운 것임을 드러냅니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_FUJI"] =
    "완벽한 화산 원뿔이 화면을 가득 채우며, 넓은 만년설 덮개가 비탈을 따라 거의 아래까지 내려옵니다. 눈은 깊은 파란 하늘을 배경으로 부드러운 흰색과 연한 파란색으로 그려져 있으며, 산기슭을 따라 초록 덤불과 안개 낀 물줄기가 띠를 이루며 놓여 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_GEYSER"] =
    "간헐천이 울퉁불퉁한 창백한 둔덕에서 분출하며, 흰 물보라가 부채꼴로 퍼져 파란 하늘을 안개로 가득 채웁니다. 짙은 상록수림이 양쪽에서 좁혀 들어오고, 전경은 황갈색, 황토색, 갈색의 광물 단구가 굳어 이룬 지각입니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_GIBRALTAR"] =
    "거대한 석회암 곶이 평평한 바다에서 솟아오르며, 왼쪽 면은 깎아지른 창백한 절벽이고 그 등줄기를 따라 짙은 초록 식생의 긴 비탈이 흘러내립니다. 장면 전체가 금빛으로 물들어 있으며, 하늘과 물이 늦은 오후처럼 빛납니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_KILIMANJARO"] =
    "거대한 눈 줄무늬가 그어진 돔이 차가운 흰색과 파란색으로 화면 위쪽 절반을 채우며, 그 기슭에는 작은 구름 띠가 떠다닙니다. 그 아래로는 초록 사바나가 펼쳐지고, 그곳에서 기린 두 마리가 창백한 물웅덩이 곁에 서 있으며, 장면 가장자리에는 꼭대기가 평평한 나무들이 자리합니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_LAKE_VICTORIA"] =
    "넓은 청록색 호수가 지평선의 창백한 언덕까지 멀리 뻗어 있으며, 양쪽으로는 바위투성이 황갈색 노두가 둘러싸고 있습니다. 중앙 전경에서는 하마 한 마리가 수면 위로 떠올라 머리와 등으로 잔물결 이는 물을 가르고 있으며, 그 위로는 하늘을 채우는 흰 빛이 어려 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_MESA"] =
    "층층이 쌓인 붉은 주황색 바위로 이루어진 꼭대기가 평평한 메사가 메마른 평원에서 홀로 솟아 있으며, 띠를 이룬 절벽 벽이 무너져 내린 암석의 긴 비탈 위에 자리합니다. 그 기슭의 모래 지면에는 드문드문 초록 관목이 점점이 박혀 있고, 평평한 정상은 밝은 파란 하늘을 배경으로 또렷한 선을 그립니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_MT_KAILASH"] =
    "띠를 이룬 바위와 눈으로 이루어진 피라미드가 깊은 파란 하늘을 배경으로 솟아 있으며, 줄무늬 진 그 면의 한쪽은 따뜻한 금빛으로 물들어 있습니다. 그 아래 전경은 온통 거친 설원과 차가운 파란 그림자 속에 잠긴 얼음 능선입니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_MT_SINAI"] =
    "주황빛 도는 갈색 사암으로 이루어진 울퉁불퉁한 사막 봉우리들이 무리 지어 있으며, 그 면에는 깊은 협곡들이 새겨져 있고, 가운데 정상 뒤에서 부드러운 빛이 비쳐 나옵니다. 맑은 파란 하늘 아래 전경의 모래 평지에는 흩어진 바위들이 널려 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_POTOSI"] =
    "헐벗은 적갈색 산으로, 그 아래쪽 비탈은 은빛 광석이 반짝이는 회색 바위 더미에 파묻혀 있습니다. 한 줄기 길이 그 옆구리를 따라 굽이쳐 오르고, 광산 갱도처럼 짙은 색의 네모난 블록들이 그 기슭에 줄지어 서 있으며, 먼지 낀 정상은 파란 하늘을 배경으로 서 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_REEF"] =
    "수중 장면입니다. 산호가 화면의 왼쪽과 아래쪽을 주황색, 빨간색, 보라색, 연한 파란색으로 가득 채우며, 그 가지들 사이로 관 모양 해면이 곧게 서 있습니다. 작은 열대어들이 짙은 파란 물속을 떠다니고, 그 중앙에는 밝은 노란색 물고기 한 마리가 있습니다. 빛은 오른쪽 위로 갈수록 어두워지며 탁 트인 어둠 속으로 잦아듭니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_SOLOMONS_MINES"] =
    "전설의 광산을 대신하는 기념비적인 성문 누각입니다. 금빛으로 끝을 마감한 흉벽이 얹힌 높고 어두운 요새 벽이 있으며, 그 중앙에는 출입구가 나 있고 양옆에는 황갈색 석조 탑이 자리합니다. 그 앞 창백한 암석 바닥은 마치 땅 자체가 매끄럽게 채석된 듯 휩쓸리는 곡선으로 깎여 있습니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_SRI_PADA"] =
    "무성한 초록 산이 둥근 봉우리까지 솟아오르며, 주황빛 도는 갈색 바위가 절벽으로 드러난 곳을 빼고는 정글이 그 비탈을 덮고 있습니다. 작은 파란 꽃이 핀 키 큰 풀잎들이 전경을 채우고, 그 뒤의 하늘은 선명한 열대의 청록색입니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_ULURU"] =
    "거대한 붉은 단일 바위가 중간 거리를 가로질러 누워 있으며, 둥근 사암 덩어리에는 세로로 골이 패여 있고 빛을 받아 주황빛으로 빛납니다. 그 앞으로는 평평한 오지의 관목 지대가 펼쳐지며, 붉은 흙이 낮은 초록 덤불과 풀숲으로 군데군데 덮여 있고, 그 위로는 밝은 파란 하늘이 자리합니다."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_VOLCANO"] =
    "어두운 화산 원뿔이 창백한 청록색 물줄기 너머 바다에서 솟아오르며, 넓은 초록 잎이 장면을 틀로 감싸는 정글 해안에서 바라본 모습입니다. 그 위 하늘은 유황빛 노란색으로 타오르고, 정상 위로 희미하게 굽이치는 연기가 다가올 분화를 암시합니다."
